/** Episode 8–10 illustrative investigation surfaces; no source measurements are implied.
 * `dispatch(choice)` passes an existing scene choice to the validated reducer. */
import {restore810} from './arc810.mjs';
const NS='http://www.w3.org/2000/svg';
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
const svgNode=(tag,attrs={})=>{const n=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));return n;};
function visual(title,description){const r=el('section');r.className='arc810-visual';r.style.cssText='border:1px solid #8aa5a4;border-radius:12px;padding:.7rem;background:#071c2a;margin:.5rem 0';r.append(el('h3',title),el('p',description));return r;}
function picture(label){const s=svgNode('svg',{viewBox:'0 0 440 160',role:'img','aria-label':label});s.style.cssText='width:100%;height:auto;max-height:160px;display:block;background:#071522;border-radius:8px';return s;}
function path(s,d,stroke,width=3,more={}){s.append(svgNode('path',{d,stroke,'stroke-width':width,fill:'none','stroke-linecap':'round',...more}));}
function label(s,x,y,text){const n=svgNode('text',{x,y,fill:'#f5e2b5','font-size':13,'font-family':'system-ui,sans-serif'});n.textContent=text;s.append(n);}
function button(root,text,choice,dispatch){const b=el('button',text);b.type='button';b.className='secondary';b.style.margin='.2rem';b.addEventListener('click',()=>dispatch(choice));root.append(b);}
function signalGraphic(which,seen){const s=picture((which==='dock'?'Dock worker':'Vendor')+' signal; '+(seen?'a supported passage is recorded':'signal not yet observed'));s.append(svgNode('rect',{x:25,y:25,width:390,height:110,rx:8,fill:'#163948',stroke:'#7ab4bf'}));label(s,44,50,which==='dock'?'DOCK WORKER':'VENDOR');label(s,44,76,seen?(which==='dock'?'INNER CHANNEL · CLEAR WINDOW':'CANAL PASSAGE · CLEAR WINDOW'):'Watch for a route warning');path(s,'M50 112 C135 92 185 132 265 106 S360 88 392 98','#74d4df',4);return s;}
function routeGraphic(s){const svg=picture('Two illustrated routes: inner channel and canal passage. The available signals are written next to each route.');path(svg,'M30 80 C95 80 120 25 210 25 S315 30 410 30','#e3c784',5);path(svg,'M30 80 C95 80 125 135 210 135 S315 130 410 130','#74d7e3',5);label(svg,135,48,'INNER CHANNEL');label(svg,135,117,'CANAL PASSAGE');label(svg,260,49,s.flags.dock_signal?'dock signal observed':'not yet supported');label(svg,260,117,s.flags.vendor_signal?'vendor signal observed':'not yet supported');return svg;}
function setupGraphic(s){const here=s.apparatus==='bench',svg=picture('Illustrative crystal experiment. Apparatus '+(here?'on the bench':s.apparatus==='carried'?'being carried':'at the '+s.apparatus)+'. '+(s.setup?`Current arrangement: ${s.setup}.`:'No arrangement selected.'));svg.append(svgNode('rect',{x:50,y:118,width:340,height:12,rx:3,fill:'#ab8d5e'}));const gem=(x)=>svg.append(svgNode('path',{d:`M${x} 30 l30 35 -30 42 -30 -42 z`,fill:'#2d7482',stroke:'#c2eef0','stroke-width':2}));if(here&&s.setup){gem(s.setup==='single'?220:180);if(s.setup==='paired')gem(260);}label(svg,75,148,here?(s.setup==='paired'?'PAIRED ARRANGEMENT':s.setup==='single'?'SINGLE CONTROL':'NO ARRANGEMENT SELECTED'):'APPARATUS NOT ON BENCH');return svg;}
function observationGraphic(id,s){const side=id==='marked-wall'?'wall':'channel',here=s.apparatus===side,key=side+'_'+s.setup,recorded=here&&!!s.setup&&s.samples[key];const svg=picture((side==='wall'?'Marked wall':'Water channel')+' observation. '+(!here?'The apparatus is not at this station.':!s.setup?'No arrangement selected.':recorded?'Observation recorded.':'Not yet observed.'));label(svg,25,25,side==='wall'?'MARKED WALL':'WATER CHANNEL');path(svg,side==='wall'?'M50 125 V45 H150 V125':'M50 112 Q95 93 140 112 T230 112 T320 112 T410 112',side==='wall'?'#d5b779':'#72d5df',5);if(here&&s.setup){svg.append(svgNode('path',{d:'M210 55 l22 25 -22 30 -22 -30 z',fill:'#2a7180',stroke:'#c2eef0','stroke-width':2}));if(s.setup==='paired')svg.append(svgNode('path',{d:'M270 55 l22 25 -22 30 -22 -30 z',fill:'#2a7180',stroke:'#c2eef0','stroke-width':2}));}if(recorded){const strength=s.setup==='paired'&&side==='wall'?22:8;for(let i=1;i<=3;i++)svg.append(svgNode('circle',{cx:240,cy:83,r:strength+i*7,fill:'none',stroke:'#afeaf0','stroke-width':2,opacity:.5}));}label(svg,25,150,!here?'APPARATUS NOT AT THIS STATION':recorded?'OBSERVATION RECORDED':'OBSERVE THE CURRENT ARRANGEMENT');return svg;}
function modelGraphic(s){const svg=picture('City model with concentric rings and the evidence strands placed so far.');for(const r of [24,48,72])svg.append(svgNode('ellipse',{cx:180,cy:80,rx:r*1.35,ry:r*.65,fill:'none',stroke:'#e6c98e','stroke-width':2}));if(s.flags.architecture){path(svg,'M180 14 V146 M85 80 H275','#f8e3b8',2,{'stroke-dasharray':'5 4'});label(svg,295,35,'ARCHITECTURE');}if(s.flags.water){path(svg,'M48 125 C110 98 225 96 310 135','#78d9e2',4);label(svg,295,65,'WATER');}if(s.flags.astronomy){for(const [x,y] of [[120,25],[180,10],[246,28]])svg.append(svgNode('circle',{cx:x,cy:y,r:4,fill:'#ffe8a8'}));label(svg,295,95,'ASTRONOMY');}return svg;}
/** `dispatch` receives a choice string; reducer alone decides if it is supported. */
export function makeArc810Visual(sceneId,objectId,state,dispatch){
 if(typeof dispatch!=='function')throw new TypeError('dispatch callback required');const s=restore810(state?.state??state);let root;
 if(sceneId==='barge-route'&&(objectId==='dock-signal'||objectId==='vendor-signal')){const dock=objectId==='dock-signal',seen=!!s.flags[dock?'dock_signal':'vendor_signal'];root=visual(dock?'Dock-worker warning':'Vendor warning','The signal is one possible source of route evidence.');root.append(signalGraphic(dock?'dock':'vendor',seen));button(root,seen?'Watch again':'Observe the signal','observe',dispatch);return root;}
 if(sceneId==='barge-route'&&objectId==='route-chart'){root=visual('Passage chart','Compare the signals with the illustrated choices. Waiting is safe.');root.append(routeGraphic(s));button(root,'Take inner channel','inner',dispatch);button(root,'Take canal passage','canal',dispatch);button(root,'Wait and reconsider','wait',dispatch);return root;}
 if(sceneId==='warehouse-experiment'&&objectId==='specimen-setup'){root=visual('Test arrangement','Keep the arrangement fixed while moving the apparatus between locations. A single crystal is an optional control.');root.append(setupGraphic(s));if(s.apparatus==='bench'){button(root,'Use paired crystals','paired',dispatch);button(root,'Use one crystal as control','single',dispatch);button(root,'Take the apparatus','take',dispatch);}else if(s.apparatus==='carried')button(root,'Place it on the bench','place',dispatch);else root.append(el('p','The apparatus is at another station. Take it there before returning.'));return root;}
 if(sceneId==='warehouse-experiment'&&(objectId==='marked-wall'||objectId==='water-channel')){const side=objectId==='marked-wall'?'wall':'channel';root=visual(objectId==='marked-wall'?'At the marked wall':'At the water channel','An illustrative view of the apparatus at this location.');root.append(observationGraphic(objectId,s));if(s.apparatus===side){button(root,'Observe this position','observe',dispatch);button(root,'Take the apparatus','take',dispatch);}else if(s.apparatus==='carried')button(root,'Place the apparatus here','place',dispatch);else root.append(el('p','The apparatus is at another station. Take it there before placing it here.'));return root;}
 if(sceneId==='warehouse-experiment'&&objectId==='experiment-notes'){root=visual('Experiment notes','Compare the same arrangement across positions; the control is optional.');root.append(el('p',`Paired: wall ${s.samples.wall_paired?'observed':'not observed'}; channel ${s.samples.channel_paired?'observed':'not observed'}. Single control: wall ${s.samples.wall_single?'observed':'not observed'}; channel ${s.samples.channel_single?'observed':'not observed'}.`));button(root,'The paired response differs between positions','localized',dispatch);button(root,'Position has no effect','same-everywhere',dispatch);button(root,'The crystals changed between tests','different-crystals',dispatch);return root;}
 if(sceneId==='city-synthesis'&&objectId==='city-model'){root=visual('City ring model','Place different evidence strands, then compare their relationships.');root.append(modelGraphic(s));button(root,'The rings connect architecture, water and resonance','resonance',dispatch);button(root,'The rings are only a trade layout','trade-only',dispatch);button(root,'The evidence has no common relationship','unrelated',dispatch);return root;}
 return null;
}
